import attr

from .connection_details import SshServiceDetails


@attr.s(cmp=False)
class ParagonX(object):
    """

    :param SshServiceDetails calnex_connection_details: Address, port, username and password used for
        connecting to Calnex server
    :param str instrument_addr: Calnex software application address
    :param int instrument_port: Calnex software application port
    """
    calnex_connection_details = attr.ib(type=SshServiceDetails)
    instrument_addr = attr.ib(type=int)
    instrument_port = attr.ib(type=str)


@attr.s(cmp=False)
class Caffeine(object):
    """

    :param str addr: Caffeine address
    :param str password: Caffeine password
    :param str trex_path: Determines where TRex script is placed on the server
    :param str config_path: Path to config file used to start TRex server
    """
    addr = attr.ib(type=str)
    password = attr.ib(type=str)
    trex_path = attr.ib(type=str)
    config_path = attr.ib(type=str)
